package org.dromara.sports.tables.d13.agent_run;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JsonNode;
import org.dromara.sports.platform.core.JsonFingerprint;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;

/** Unit policy boundaries only; real MCP/model/roles are verified separately. */
@Tag("local") class AgentPlaybookRulesTest {
    final ObjectMapper json=new ObjectMapper();
    JsonNode stored()throws Exception{return json.readTree("""
      {"tools":{"entries":[{"name":"sports_playbook","agentAllowed":true},{"name":"sports_execute","agentAllowed":false},{"name":"sports_event_query_public","agentAllowed":false},{"name":"raw_sql"}]},"skills":{"entries":[{"code":"team","actors":["platform"]},{"code":"organize","actors":["organizer"]}]},"businessMap":{"flows":[{"code":"organize","actors":["organizer"],"steps":[{"capabilities":["event.publish"],"path":"/org-desk/workspace/{eventId}?task=publication"}]},{"code":"join","actors":["platform"],"steps":[{"capabilities":["room.query"],"path":"/portal/rooms"}]}]}}
      """);}
    @Test void alteredCatalogStopsBeforeAnyGuidance()throws Exception{assertThrows(RuntimeException.class,()->AgentPlaybookRules.filter(json,stored(),"0".repeat(64),2,"platform",json.createArrayNode(),json.createObjectNode()));}
    @Test void currentRoleAndRealOpenChannelsFilterSkillsAndFlows()throws Exception{var s=stored();var actions=json.readTree("[{\"code\":\"room.query\",\"uiEnabled\":true,\"agentEnabled\":false,\"reads\":[\"private_table\"]}]");var filtered=AgentPlaybookRules.filter(json,s,JsonFingerprint.hash(s),2,"platform",actions,json.createObjectNode());assertEquals(1,filtered.path("skills").size());assertEquals("join",filtered.path("businessMap").path("flows").get(0).path("code").asText());assertEquals(1,filtered.path("toolCatalog").path("entries").size());assertFalse(filtered.toString().contains("sports_event_query_public"));assertFalse(filtered.toString().contains("sports_execute"));assertFalse(filtered.toString().contains("private_table"));assertFalse(filtered.toString().contains("raw_sql"));assertFalse(filtered.path("actions").get(0).path("agentEnabled").asBoolean());}
    @Test void modelCannotSupplyExternalPathsCompletionOrReceipts()throws Exception{var s=stored();var a=json.readTree("[{\"code\":\"room.query\",\"uiEnabled\":true,\"agentEnabled\":false}]");var book=AgentPlaybookRules.filter(json,s,JsonFingerprint.hash(s),2,"platform",a,json.createObjectNode());var blocks=AgentPlaybookRules.blocks(json,json.readTree("[{\"kind\":\"navigation\",\"code\":\"room.query\",\"path\":\"https://evil.invalid\",\"label\":\"集结\"},{\"kind\":\"receipt\",\"receiptId\":\"fake\"},{\"kind\":\"checklist\",\"items\":[{\"label\":\"已收款\",\"state\":\"done\"}]}]"),book);assertEquals(2,blocks.size());assertEquals("/portal/rooms",blocks.get(0).path("path").asText());assertEquals("todo",blocks.get(1).path("items").get(0).path("state").asText());assertFalse(blocks.toString().contains("fake"));var many=json.createArrayNode();for(int i=0;i<5;i++)many.add(json.createObjectNode().put("kind","question").put("label","需要补充"));assertEquals(3,AgentPlaybookRules.blocks(json,many,book).size());}
    @Test void unavailableChannelOrMissingContextNeverBecomesNavigation()throws Exception{var s=stored();var a=json.readTree("[{\"code\":\"event.publish\",\"uiEnabled\":true,\"agentEnabled\":false}]");var book=AgentPlaybookRules.filter(json,s,JsonFingerprint.hash(s),2,"organizer",a,json.createObjectNode());assertEquals(0,AgentPlaybookRules.blocks(json,json.readTree("[{\"kind\":\"navigation\",\"code\":\"event.publish\"}]"),book).size());var closed=AgentPlaybookRules.filter(json,s,JsonFingerprint.hash(s),2,"organizer",json.createArrayNode(),json.createObjectNode().put("eventId","99"));assertEquals(0,closed.path("actions").size());assertFalse(closed.path("businessMap").path("flows").get(0).path("steps").get(0).has("path"));}
}
